using System.Numerics;
namespace BobbyBoi;
static class IconBuilder {
 public static void Run(){Directory.CreateDirectory("assets");var mesh=new VoxelMesh();foreach(var face in ModelAsset.Load().Faces.Where(f=>f.Part=="Head"&&f.Points.All(p=>p[1]>=23.5f)))mesh.Faces.Add((face.Points.Select(p=>new Vector3(p[0],p[1]-23,p[2])).ToArray(),Color.FromArgb(face.Color[0],face.Color[1],face.Color[2]),face.Part));using var portrait=new Bitmap(256,256);using(var g=Graphics.FromImage(portrait))mesh.Draw(g,new(128,211),17,.65f);portrait.Save("assets/icon-preview.png");var sizes=new[]{16,24,32,48,64,128,256};var images=new List<byte[]>();foreach(int size in sizes){using var image=new Bitmap(size,size);using(var g=Graphics.FromImage(image)){g.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.NearestNeighbor;g.PixelOffsetMode=System.Drawing.Drawing2D.PixelOffsetMode.Half;g.DrawImage(portrait,new Rectangle(0,0,size,size));}using var data=new MemoryStream();image.Save(data,System.Drawing.Imaging.ImageFormat.Png);images.Add(data.ToArray());}using var output=new BinaryWriter(File.Create("assets/BobbyBoi.ico"));output.Write((ushort)0);output.Write((ushort)1);output.Write((ushort)sizes.Length);int offset=6+sizes.Length*16;for(int i=0;i<sizes.Length;i++){output.Write((byte)(sizes[i]==256?0:sizes[i]));output.Write((byte)(sizes[i]==256?0:sizes[i]));output.Write((byte)0);output.Write((byte)0);output.Write((ushort)1);output.Write((ushort)32);output.Write(images[i].Length);output.Write(offset);offset+=images[i].Length;}foreach(var bytes in images)output.Write(bytes);}
}
